    """An ISO 8601 time with `Z` or an offset, or None."""
    if not isinstance(text, str) or "T" not in text:
        return None
    try:
        value = datetime.fromisoformat(text)
    except ValueError:
        return None
    return value if value.tzinfo is not None else None


def parse_state_time(value):
    if not isinstance(value, str):
        return None
    if _LEGACY.match(value):
        try:
            return datetime.fromisoformat(value).replace(tzinfo=timezone.utc)
        except ValueError:
            return None
    return parse_aware(value)


def _whole(value):
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def _check_entry(name, entry):
    def bad(what):
        return DataError("state", f"state.json: {name}: {what}")

    if "opened" in entry and parse_state_time(entry["opened"]) is None:
        raise bad("opened is not a time")
    if "rotations" in entry and not _whole(entry["rotations"]):
        raise bad("rotations is not a whole number")
    if "archives" in entry:
        archives = entry["archives"]
        if not isinstance(archives, dict):
            raise bad("archives is not an object")
        for archive, value in archives.items():
            if parse_state_time(value) is None:
                raise bad(f"time of {archive} is not a time")


class Archive:
    def __init__(self, name, key, compressed):
        self.name = name
        self.key = key
        self.compressed = compressed
        self.new = False
        self.new_name = name
        self.compress = False
        self.removed = False


def _find_archives(data, name, naming):
    directory = streams.logs_dir(data)
    prefix = f"{name}.log."
    found = []
    seen = set()
    if directory.is_dir():
        for path in directory.iterdir():
            if not path.is_file() or not path.name.startswith(prefix):
                continue
            rest = path.name[len(prefix):]
            if naming == "numbered":
                match = _NUMBERED.match(rest)
                if not match:
                    continue
                key = (int(match.group(1)),)
                compressed = bool(match.group(2))
            else:
                match = _DATED.match(rest)
                if not match:
                    continue
                try:
                    day = date.fromisoformat(match.group(1))
                except ValueError:
                    continue
                key = (day, int(match.group(2) or 1))
                compressed = bool(match.group(3))
