def _archive_name(name, naming, key, compressed):
    suffix = ".gz" if compressed else ""
    if naming == "numbered":
        return f"{name}.log.{key[0]}{suffix}"
    day, count = key
    middle = "" if count == 1 else f".{count}"
    return f"{name}.log.{day.isoformat()}{middle}{suffix}"


