    try:
        with path.open("rb") as f:
            line = f.readline()
        text = line.decode("utf-8")
    except (OSError, UnicodeDecodeError):
        return None
    text = text.rstrip("\r\n")
    return parse_aware(text.split(" ", 1)[0])


