                used = {a.key[1] for a in archives if a.key[0] == day}
                if not used:
                    count = 1
                else:
                    count = 2
                    while count in used:
                        count += 1
                key = (day, count)
            new = Archive(None, key, False)
            new.new = True
            archives = archives + [new]
        archives.sort(key=lambda a: a.key)
        if pol.naming == "numbered" and new is not None:
            archives.sort(key=lambda a: (a.key[0] if not a.new else 0))

