                archive.removed = True
            elif pol.keep_days is not None and not archive.new and archive.name in times:
                when = parse_state_time(times[archive.name])
                if now - when >= timedelta(days=pol.keep_days):
                    archive.removed = True
        remaining = [a for a in archives if not a.removed]
        compressed_count = 0
        for position, archive in enumerate(remaining, 1):
            archive.compress = position > pol.compress_after and not archive.compressed
            final_compressed = archive.compressed or archive.compress
            if pol.naming == "numbered":
                key = (position,)
            else:
                key = archive.key
            archive.new_name = _archive_name(name, pol.naming, key, final_compressed)
            if archive.new:
                archive.name = _archive_name(name, pol.naming, archive.key, False)
            compressed_count += archive.compress

        out.append(f"{name}: {what if not rotated else f'rotate ({what})'}")
        new_times = {}
        for archive in remaining:
            if archive.new:
                out.append(f"  new {archive.new_name}")
                new_times[archive.new_name] = dates.stamp(now)
            elif archive.new_name != archive.name:
                out.append(f"  {archive.new_name} <- {archive.name}")
            else:
                out.append(f"  {archive.name}")
            if not archive.new and archive.name in times:
                new_times[archive.new_name] = times[archive.name]
        for archive in archives:
            if archive.removed:
                out.append(f"  remove {archive.name}")
                removed_count += 1
        out.append("")
        totals[0] += rotated
        totals[1] += removed_count
        totals[2] += compressed_count
        out.pop()

        new_entry = {}
        if rotated:
            new_entry["opened"] = dates.stamp(now)
        elif "opened" in entry:
            new_entry["opened"] = entry["opened"]
        new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        new_entry["archives"] = new_times
        new_entries[name] = new_entry

        directory = streams.logs_dir(data)
        if rotated:
            writes.append(("active", log))
        for archive in archives:
            if archive.new:
                continue
            if archive.removed:
                removals.append(directory / archive.name)
            elif archive.new_name != archive.name:
                removals.append(directory / archive.name)
                writes.append(("move", directory / archive.name, directory / archive.new_name, archive.compress))
        if new is not None and not new.removed:
            writes.append(("new", log, directory / new.new_name, new.new_name.endswith(".gz")))

    out.append(f"{totals[0]} rotated, {totals[1]} removed, {totals[2]} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    contents = []
    for write in writes:
        if write[0] == "move":
            contents.append((write[2], write[1].read_bytes(), write[3]))
        elif write[0] == "new":
            contents.append((write[2], write[1].read_bytes(), write[3]))
    for path in removals:
        path.unlink()
    for target, raw, compress in contents:
        target.write_bytes(gzip.compress(raw, mtime=0) if compress else raw)
    for write in writes:
        if write[0] == "active":
            write[1].write_bytes(b"")
    entries.update(new_entries)
    state.save(ctx.state_path, doc)
    return out
