    if "rotations" in entry and not _whole(entry["rotations"]):
        raise bad("rotations is not a whole number")
    if "archives" in entry:
        archives = entry["archives"]
        if not isinstance(archives, dict):
            raise bad("archives is not an object")
        for archive, value in archives.items():
            if parse_state_time(value) is None:
                raise bad(f"time of {archive} is not a time")


class Archive:
    def __init__(self, name, key, compressed, new=False):
        self.name = name
        self.key = key
        self.compressed = compressed
        self.new = new
        self.new_name = name
        self.compress = False
        self.removed = False


def _archive_name(name, naming, key, compressed):
    suffix = ".gz" if compressed else ""
    if naming == "numbered":
        return f"{name}.log.{key[0]}{suffix}"
    day, count = key
    middle = "" if count == 1 else f".{count}"
    return f"{name}.log.{day.isoformat()}{middle}{suffix}"


def _find_archives(data, name, naming):
    directory = streams.logs_dir(data)
    prefix = f"{name}.log."
    found = []
    seen = set()
    if directory.is_dir():
        for path in directory.iterdir():
            if not path.is_file() or not path.name.startswith(prefix):
                continue
            rest = path.name[len(prefix):]
            if naming == "numbered":
                match = _NUMBERED.match(rest)
                if not match:
                    continue
                key = (int(match.group(1)),)
                compressed = bool(match.group(2))
            else:
                match = _DATED.match(rest)
                if not match:
                    continue
                try:
                    day = date.fromisoformat(match.group(1))
                except ValueError:
                    continue
                key = (day, int(match.group(2) or 1))
                compressed = bool(match.group(3))
            if key in seen:
                raise DataError("archives", f"{name}: two archives in the same place")
            seen.add(key)
            found.append(Archive(path.name, key, compressed))
    return found


def _first_line_time(path):
    try:
        with path.open("rb") as f:
            line = f.readline()
        text = line.decode("utf-8")
    except (OSError, UnicodeDecodeError):
        return None
    return parse_aware(text.rstrip("\r\n").split(" ", 1)[0])


def _new_key(pol, archives, now):
    if pol.naming == "numbered":
        return (0,)
    day = now.astimezone(timezone(timedelta(minutes=pol.offset_minutes))).date()
    used = {a.key[1] for a in archives if a.key[0] == day}
    count = 1 if not used else 2
    while count in used:
        count += 1
    return (day, count)


def _decide(pol, entry, log, force, now):
    if not log.is_file():
        return "no log"
    size = log.stat().st_size
    if size == 0:
        return "empty"
    if force:
        return "forced"
    if pol.max_size is not None and size >= pol.max_size:
        return "size"
    if pol.max_age is not None:
        opened = parse_state_time(entry["opened"]) if "opened" in entry else _first_line_time(log)
        if opened is not None and now - opened >= timedelta(minutes=pol.max_age):
            return "age"
    return "not due"


def run(ctx, names, dry_run, force):
    data = ctx.data
    policies = policy.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(data)) | policies.stream_names()
    entries = doc["streams"]
    for name in sorted(existing):
        if name in entries:
            _check_entry(name, entries[name])
    if names:
        selected = sorted(set(names))
        for name in selected:
            if name not in existing:
                raise Refused("unknown-stream", f"no stream {name}")
    else:
        selected = sorted(existing)
    plans = [(name, policies.get(name)) for name in selected]
    found = {name: _find_archives(data, name, pol.naming) for name, pol in plans}

    now = ctx.now
    directory = streams.logs_dir(data)
    out = []
    removals = []
    moves = []
    new_files = []
    truncates = []
    new_entries = {}
    totals = [0, 0, 0]
    for name, pol in plans:
        entry = entries.get(name, {})
        log = streams.log_path(data, name)
        what = _decide(pol, entry, log, force, now)
        rotated = what in ("forced", "size", "age")
        times = entry.get("archives", {})
        archives = found[name]
        if rotated:
            key = _new_key(pol, archives, now)
            new = Archive(None if pol.naming == "numbered" else _archive_name(name, pol.naming, key, False), key, False, True)
            archives = archives + [new]
        archives.sort(key=lambda a: a.key)

        for position, archive in enumerate(archives, 1):
            if position > pol.keep:
                archive.removed = True
            elif pol.keep_days is not None and not archive.new and archive.name in times:
                if now - parse_state_time(times[archive.name]) >= timedelta(days=pol.keep_days):
                    archive.removed = True
        remaining = [a for a in archives if not a.removed]
        compressed_count = 0
        for position, archive in enumerate(remaining, 1):
            archive.compress = position > pol.compress_after and not archive.compressed
            key = (position,) if pol.naming == "numbered" else archive.key
            archive.new_name = _archive_name(name, pol.naming, key, archive.compressed or archive.compress)
            if archive.new and archive.name is None:
                archive.name = _archive_name(name, pol.naming, archive.key, False)
            compressed_count += archive.compress

        out.append(f"{name}: rotate ({what})" if rotated else f"{name}: {what}")
        new_times = {}
        for archive in remaining:
            if archive.new:
                out.append(f"  new {archive.new_name}")
                new_times[archive.new_name] = dates.stamp(now)
                new_files.append((log, directory / archive.new_name, archive.compress))
                continue
            if archive.new_name != archive.name:
                out.append(f"  {archive.new_name} <- {archive.name}")
                removals.append(directory / archive.name)
                moves.append((directory / archive.name, directory / archive.new_name, archive.compress))
            else:
                out.append(f"  {archive.name}")
            if archive.name in times:
                new_times[archive.new_name] = times[archive.name]
        removed_count = 0
        for archive in archives:
            if archive.removed:
                out.append(f"  remove {archive.name}")
                removed_count += 1
                if not archive.new:
                    removals.append(directory / archive.name)
        if rotated:
            truncates.append(log)
        totals[0] += rotated
        totals[1] += removed_count
        totals[2] += compressed_count

        new_entry = {}
        if rotated:
            new_entry["opened"] = dates.stamp(now)
        elif "opened" in entry:
            new_entry["opened"] = entry["opened"]
        new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        new_entry["archives"] = new_times
        new_entries[name] = new_entry

    out.append(f"{totals[0]} rotated, {totals[1]} removed, {totals[2]} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    contents = [(target, source.read_bytes(), compress) for source, target, compress in moves + new_files]
    for path in removals:
        path.unlink()
    for target, raw, compress in contents:
        target.write_bytes(gzip.compress(raw, mtime=0) if compress else raw)
    for log in truncates:
        log.write_bytes(b"")
    entries.update(new_entries)
    state.save(ctx.state_path, doc)
    return out
